"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";

export default function OpportunityCard({ data, locale }) {
  const pathname = usePathname();
  const currentLocale = locale || pathname.split("/")[1]; // "en" or "es"

  // Sanity image URL
  const imageUrl = data.hero?.asset?.url;

  // Bilingual fields
  const title = currentLocale === "es" ? data.title_es : data.title_en;
  const vocation = currentLocale === "es" ? data.vocation_es : data.vocation_en;
  const availability = currentLocale === "es" ? data.availability_es : data.availability_en;

  // Correct dynamic route
  const route =
    currentLocale === "es"
      ? `/es/oportunidades/${data.slug.current}`
      : `/en/opportunities/${data.slug.current}`;

  return (
    <motion.div
      initial={{ opacity: 0, y: 30 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.5 }}
    >
    <Link href={route} className="block group">
      <div className="rounded-xl overflow-hidden shadow-lg bg-white transition-transform duration-300 group-hover:-translate-y-2">

        {/* Image */}
        <div
          className="h-56 bg-cover bg-center"
          style={{ backgroundImage: `url(${imageUrl})` }}
        />

        {/* Content */}
        <div className="p-6">
          <h3 className="text-xl font-bold mb-2">{title}</h3>

          <p className="text-gray-600 text-sm mb-4">
            {vocation} • {data.surface}
          </p>

          <p className="text-gray-800 font-medium mb-4">
            {availability}
          </p>

          <button className="px-4 py-2 bg-black text-white rounded-full text-sm">
            {currentLocale === "es" ? "Ver oportunidad" : "View opportunity"}
          </button>
        </div>
      </div>
    </Link>
  </motion.div>
  );
}
