"use client";

import { useForm } from "react-hook-form";
import { z } from "zod";
import { zodResolver } from "@hookform/resolvers/zod";
import { useState } from "react";

const LeadSchema = z.object({
  name: z.string().min(2, "Name is too short"),
  email: z.string().email("Invalid email"),
  phone: z.string().min(8, "Phone number is too short"),
  message: z.string().min(10, "Message must be at least 10 characters")
});

export default function LeadForm() {
  const [submitted, setSubmitted] = useState(false);

  const {
    register,
    handleSubmit,
    formState: { errors, isSubmitting }
  } = useForm({
    resolver: zodResolver(LeadSchema)
  });

  async function onSubmit(data) {
    const res = await fetch("/api/lead", {
      method: "POST",
      body: JSON.stringify(data)
    });

    if (res.ok) {
      setSubmitted(true);
    }
  }

  if (submitted) {
    return (
      <div className="p-10 bg-green-100 rounded-xl text-center">
        <h3 className="text-2xl font-bold mb-2">Thank you!</h3>
        <p>We received your information and will contact you shortly.</p>
      </div>
    );
  }

  return (
    <form
      onSubmit={handleSubmit(onSubmit)}
      className="max-w-xl mx-auto bg-white p-10 rounded-xl shadow-lg space-y-6"
    >
      <div>
        <label className="block font-semibold mb-1">Name</label>
        <input
          {...register("name")}
          className="w-full border p-3 rounded"
        />
        {errors.name && (
          <p className="text-red-600 text-sm">{errors.name.message}</p>
        )}
      </div>

      <div>
        <label className="block font-semibold mb-1">Email</label>
        <input
          {...register("email")}
          className="w-full border p-3 rounded"
        />
        {errors.email && (
          <p className="text-red-600 text-sm">{errors.email.message}</p>
        )}
      </div>

      <div>
        <label className="block font-semibold mb-1">Phone</label>
        <input
          {...register("phone")}
          className="w-full border p-3 rounded"
        />
        {errors.phone && (
          <p className="text-red-600 text-sm">{errors.phone.message}</p>
        )}
      </div>

      <div>
        <label className="block font-semibold mb-1">Message</label>
        <textarea
          {...register("message")}
          className="w-full border p-3 rounded h-32"
        />
        {errors.message && (
          <p className="text-red-600 text-sm">{errors.message.message}</p>
        )}
      </div>

      <button
        disabled={isSubmitting}
        className="w-full bg-black text-white py-3 rounded-full font-semibold"
      >
        {isSubmitting ? "Sending..." : "Send"}
      </button>
    </form>
  );
}
